--
-- Name: mv_research_funding_summary; Type: MATERIALIZED VIEW; Schema: landing; Owner: -
--

CREATE MATERIALIZED VIEW landing.mv_research_funding_summary AS
 SELECT unitid,
    count(*) AS award_count_total,
    count(*) FILTER (WHERE (fiscal_year >= ((EXTRACT(year FROM CURRENT_DATE))::integer - 3))) AS award_count_last_3y,
    sum(amount_total_usd) AS amount_total_all_time_usd,
    sum(amount_total_usd) FILTER (WHERE (fiscal_year >= ((EXTRACT(year FROM CURRENT_DATE))::integer - 3))) AS amount_total_last_3y_usd,
    max(end_date) AS latest_award_end,
    count(*) FILTER (WHERE (source_system = 'nih_reporter'::text)) AS award_count_nih,
    count(*) FILTER (WHERE (source_system = 'nsf_awards'::text)) AS award_count_nsf,
    count(*) FILTER (WHERE (source_system = 'usaspending'::text)) AS award_count_usaspending,
    sum(amount_total_usd) FILTER (WHERE (source_system = 'nih_reporter'::text)) AS amount_nih_usd,
    sum(amount_total_usd) FILTER (WHERE (source_system = 'nsf_awards'::text)) AS amount_nsf_usd,
    sum(amount_total_usd) FILTER (WHERE (source_system = 'usaspending'::text)) AS amount_usaspending_usd
   FROM landing.research_awards
  GROUP BY unitid
  WITH NO DATA;


