--
-- Name: mv_institution_page; Type: MATERIALIZED VIEW; Schema: landing; Owner: -
--

CREATE MATERIALIZED VIEW landing.mv_institution_page AS
 SELECT li.unitid,
    li.slug,
    li.name AS institution_name,
    li.city,
    li.stabbr,
    li.state_name,
    li.state_slug,
    li.region,
    li.zip,
    li.webaddr_normalized AS webaddr,
    li.canonical_root_url,
    li.domain,
    li.registrable_domain,
    li.opeid,
    li.ein,
    li.ueis,
    li.control_label,
    li.control_slug,
    li.sector_label,
    li.carnegie_basic_label,
    li.carnegie_basic_slug,
    li.is_hbcu,
    li.is_tribal,
    li.is_hospital,
    li.is_medical,
    li.is_landgrant,
    li.is_hsi,
    sc_latest.scorecard,
    ( SELECT to_jsonb(b.*) AS to_jsonb
           FROM landing.brand_assets b
          WHERE (b.unitid = li.unitid)) AS brand,
    ( SELECT to_jsonb(w.*) AS to_jsonb
           FROM landing.wiki_summaries w
          WHERE (w.unitid = li.unitid)) AS wiki,
    ( SELECT to_jsonb(irp.*) AS to_jsonb
           FROM landing.ir_pages irp
          WHERE (irp.unitid = li.unitid)) AS ir_page,
    ( SELECT to_jsonb(rfs.*) AS to_jsonb
           FROM landing.mv_research_funding_summary rfs
          WHERE (rfs.unitid = li.unitid)) AS research_summary,
    ( SELECT COALESCE(jsonb_agg(to_jsonb(ic.*) ORDER BY ic.ordering, ic.id), '[]'::jsonb) AS "coalesce"
           FROM landing.ir_contacts ic
          WHERE (ic.unitid = li.unitid)) AS ir_contacts,
    ( SELECT COALESCE(jsonb_agg(to_jsonb(d.*) ORDER BY d.year DESC NULLS LAST, d.id), '[]'::jsonb) AS "coalesce"
           FROM landing.ir_documents d
          WHERE (d.unitid = li.unitid)) AS documents,
    ( SELECT COALESCE(jsonb_agg(to_jsonb(cds.*) ORDER BY cds.year DESC, cds.id), '[]'::jsonb) AS "coalesce"
           FROM landing.cds_links cds
          WHERE (cds.unitid = li.unitid)) AS cds_links,
    ( SELECT COALESCE(jsonb_agg(to_jsonb(j.*) ORDER BY j.posted_at DESC NULLS LAST, j.id), '[]'::jsonb) AS "coalesce"
           FROM landing.job_postings j
          WHERE (j.unitid = li.unitid)) AS jobs,
    ( SELECT COALESCE(jsonb_agg(to_jsonb(na.*) ORDER BY na.id), '[]'::jsonb) AS "coalesce"
           FROM landing.notable_alumni na
          WHERE (na.unitid = li.unitid)) AS notable_alumni,
    ( SELECT COALESCE(jsonb_agg(to_jsonb(pg.*) ORDER BY pg.rank), '[]'::jsonb) AS "coalesce"
           FROM landing.peer_groups pg
          WHERE ((pg.unitid = li.unitid) AND (pg.algorithm = 'carnegie_state_control_v1'::text))) AS peers,
    ( SELECT COALESCE(jsonb_agg(to_jsonb(rx.*) ORDER BY rx.fiscal_year DESC), '[]'::jsonb) AS "coalesce"
           FROM landing.research_expenditures rx
          WHERE (rx.unitid = li.unitid)) AS research_expenditures,
    GREATEST(( SELECT brand_assets.fetched_at
           FROM landing.brand_assets
          WHERE (brand_assets.unitid = li.unitid)), ( SELECT wiki_summaries.fetched_at
           FROM landing.wiki_summaries
          WHERE (wiki_summaries.unitid = li.unitid)), ( SELECT ir_pages.fetched_at
           FROM landing.ir_pages
          WHERE (ir_pages.unitid = li.unitid))) AS landing_last_updated_at
   FROM (landing.institutions li
     LEFT JOIN LATERAL ( SELECT to_jsonb(sc.*) AS scorecard
           FROM score_card.fact_institution_yearly sc
          WHERE (sc.institution_id = li.unitid)
          ORDER BY sc.academic_year_id DESC
         LIMIT 1) sc_latest ON (true))
  WHERE li.enabled
  WITH NO DATA;


