--
-- Name: v_carnegie_counts; Type: VIEW; Schema: landing; Owner: -
--

CREATE VIEW landing.v_carnegie_counts AS
 SELECT carnegie_basic_slug,
    carnegie_basic_code,
    carnegie_basic_label,
    count(*) AS institution_count
   FROM landing.institutions
  WHERE (enabled AND (carnegie_basic_slug IS NOT NULL))
  GROUP BY carnegie_basic_slug, carnegie_basic_code, carnegie_basic_label;


--
-- Name: v_state_counts; Type: VIEW; Schema: landing; Owner: -
--

CREATE VIEW landing.v_state_counts AS
 SELECT state_slug,
    stabbr,
    state_name,
    region,
    count(*) AS institution_count,
    sum(
        CASE
            WHEN is_hbcu THEN 1
            ELSE 0
        END) AS hbcu_count,
    sum(
        CASE
            WHEN is_tribal THEN 1
            ELSE 0
        END) AS tribal_count
   FROM landing.institutions
  WHERE enabled
  GROUP BY state_slug, stabbr, state_name, region;


